.netadvsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e6edf5;
    background:
        radial-gradient(circle at 18% 12%, rgba(45, 212, 191, 0.10) 0%, rgba(45, 212, 191, 0) 42%),
        radial-gradient(circle at 86% 78%, rgba(245, 158, 11, 0.08) 0%, rgba(245, 158, 11, 0) 46%),
        linear-gradient(160deg, #0b1220 0%, #111c2e 55%, #0d1626 100%);
    border-radius: 18px;
}

.netadvsim-container * {
    box-sizing: border-box;
}

.netadvsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #0e1f33 0%, #123a4a 55%, #0f5e63 100%);
    color: #eafcfb;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid rgba(45, 212, 191, 0.22);
    box-shadow: 0 12px 34px rgba(0, 0, 0, 0.45);
}

.netadvsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #f4fbfa;
}

.netadvsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #7fe7d8;
    background: rgba(45, 212, 191, 0.14);
    padding: 5px 14px;
    border-radius: 999px;
    border: 1px solid rgba(45, 212, 191, 0.25);
}

.netadvsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #c5d6e6;
}

.netadvsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #aebfd2;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.netadvsim-period-counter #currentDay,
.netadvsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #2dd4bf;
}

.netadvsim-round-name {
    background: rgba(45, 212, 191, 0.16);
    color: #7fe7d8;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid rgba(45, 212, 191, 0.28);
}

.netadvsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #fcd9a0;
    background: rgba(245, 158, 11, 0.16);
    padding: 4px 12px;
    border-radius: 999px;
    border: 1px solid rgba(245, 158, 11, 0.30);
}

.netadvsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.netadvsim-status-card {
    background: linear-gradient(165deg, #142337 0%, #0f1b2c 100%);
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #25344a;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);
    border-top: 4px solid #2dd4bf;
}

.netadvsim-card-centrality { border-top-color: #2dd4bf; }
.netadvsim-card-approp { border-top-color: #f59e0b; }
.netadvsim-card-trust { border-top-color: #60a5fa; }
.netadvsim-card-budget { border-top-color: #a78bfa; }

.netadvsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8597ad;
}

.netadvsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #f4fbfa;
}

.netadvsim-card-centrality .netadvsim-value { color: #2dd4bf; }
.netadvsim-card-approp .netadvsim-value { color: #f59e0b; }
.netadvsim-card-trust .netadvsim-value { color: #60a5fa; }
.netadvsim-card-budget .netadvsim-value { color: #a78bfa; }

.netadvsim-sublabel {
    font-size: 0.76rem;
    color: #7c8fa6;
    line-height: 1.35;
}

.netadvsim-centrality-strong .netadvsim-value { color: #34d399; }
.netadvsim-trust-low .netadvsim-value { color: #f87171; }
.netadvsim-budget-over { border-top-color: #f87171; }
.netadvsim-budget-over .netadvsim-value { color: #f87171; }

.netadvsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0a1322;
    color: #d8e4f2;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border: 1px solid #243349;
}

.netadvsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #fcd9a0;
}

.netadvsim-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(165deg, #142337 0%, #0f1b2c 100%);
    border-left: 5px solid #2dd4bf;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.30);
}

.netadvsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.netadvsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #7fe7d8;
    margin-bottom: 6px;
}

.netadvsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #c5d6e6;
}

.netadvsim-briefing-text strong { color: #34d399; }
.netadvsim-briefing-text em { color: #fcd9a0; font-style: italic; }

.netadvsim-controls {
    background: linear-gradient(165deg, #142337 0%, #0f1b2c 100%);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #25344a;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.30);
}

.netadvsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #eafcfb;
    border-bottom: 2px solid #25344a;
    padding-bottom: 8px;
}

.netadvsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #cdddee;
    margin: 14px 0 6px;
}

.netadvsim-container select,
.netadvsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2c3e57;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0c1626;
    color: #e6edf5;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.netadvsim-container select:focus,
.netadvsim-container input[type="number"]:focus {
    outline: none;
    border-color: #2dd4bf;
    box-shadow: 0 0 0 3px rgba(45, 212, 191, 0.20);
}

.netadvsim-container select option {
    background-color: #0c1626;
    color: #e6edf5;
}

.netadvsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2dd4bf;
}

.netadvsim-range-readout,
.netadvsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fc7e8;
    margin-top: 4px;
}

.netadvsim-range-readout span:last-child,
.netadvsim-alloc-readout span:nth-child(2) {
    color: #34d399;
    font-weight: 800;
}

.netadvsim-hint {
    font-size: 0.8rem;
    color: #7c8fa6;
    margin-top: 4px;
    line-height: 1.4;
}

.netadvsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.netadvsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #0c1626;
    border: 1px solid #243349;
    border-radius: 9px;
    padding: 8px 12px;
}

.netadvsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #cdddee;
}

.netadvsim-alloc-row input[type="number"] {
    width: 96px;
    flex: 0 0 96px;
}

.netadvsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.netadvsim-container .btn-primary {
    background: linear-gradient(135deg, #0f766e 0%, #2dd4bf 100%);
    border: none;
    color: #04221f;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 18px rgba(45, 212, 191, 0.30);
}

.netadvsim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.netadvsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #2c3e57;
    color: #9fb2c9;
    background: transparent;
}

.netadvsim-coach {
    background: linear-gradient(135deg, #0e1f33 0%, #123a4a 100%);
    color: #d8e9ef;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid rgba(45, 212, 191, 0.18);
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.38);
}

.netadvsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #7fe7d8;
    margin-bottom: 8px;
}

.netadvsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.netadvsim-coach-body strong { color: #fcd9a0; }
.netadvsim-coach-body em { color: #ffb4a2; font-style: italic; }

.netadvsim-history,
.netadvsim-chart {
    background: linear-gradient(165deg, #142337 0%, #0f1b2c 100%);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #25344a;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.30);
}

.netadvsim-history h3,
.netadvsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #eafcfb;
}

.netadvsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #cdddee;
}

.netadvsim-container table#usfHistoryTable th {
    background: #0c1626;
    color: #7fe7d8;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #25344a;
}

.netadvsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #1c2a3e;
}

.netadvsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: rgba(255, 255, 255, 0.02);
}

.netadvsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .netadvsim-container {
        padding: 14px;
    }
    .netadvsim-header h1 {
        font-size: 1.7rem;
    }
    .netadvsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .netadvsim-value {
        font-size: 2rem;
    }
    .netadvsim-clock {
        margin-left: 0;
    }
    .netadvsim-period-counter {
        font-size: 0.88rem;
    }
    .netadvsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .netadvsim-alloc-row {
        flex-wrap: wrap;
    }
    .netadvsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .netadvsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

