(function() {
    'use strict';

    class NetworkAdvantageAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Network Advantage`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (deals quoted in USD).
            this.START_CENTRALITY = 18;     // peripheral but uniquely positioned
            this.START_APPROP = 12;         // creating value, capturing almost none yet
            this.START_TRUST = 50;          // neutral standing across partners
            this.BUDGET_CAP = 28;           // USD 28M, in $M
            this.POSITION_CAP = 4;          // can resource 3-4 properly
            this.TARGET_CENTRALITY = 70;    // durable broker position
            this.TARGET_APPROP = 65;        // rent actually captured
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    centrality: this.START_CENTRALITY,
                    approp: this.START_APPROP,
                    trust: this.START_TRUST,
                    budgetUsed: 0,
                    positions: 0,
                    straddled: false,
                    leaked: false,
                    disintermediated: false,
                    centralityHistory: [this.START_CENTRALITY],
                    appropHistory: [this.START_APPROP],
                    trustHistory: [this.START_TRUST],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are deliberately a MIXED, non-winning play (no auto-win on click-through).
                state.decisions = {
                    diag: `technology`,
                    hole: `central`,
                    search: 55,
                    shape: `manyshallow`,
                    conflict: `both`,
                    brokerSpend: 16,
                    depthSpend: 9,
                    peripherySpend: 3,
                    ultimatum: `cave`,
                    brokerStance: `broadcast`,
                    innovation: `open`,
                    lockinSpend: 5,
                    appropriate: `goodwill`,
                    reoptimize: `expand`,
                    feedbackRule: `vanity`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const diag = document.getElementById(`diagInput`);
                const hole = document.getElementById(`holeInput`);
                const search = document.getElementById(`searchInput`);
                if (diag) decisions.diag = diag.value;
                if (hole) decisions.hole = hole.value;
                if (search) decisions.search = parseInt(search.value, 10);
                if (!Number.isFinite(decisions.search) || decisions.search < 0 || decisions.search > 100) {
                    warn(`warn_search_range`); return false;
                }
            } else if (round === 2) {
                const shape = document.getElementById(`shapeInput`);
                const conflict = document.getElementById(`conflictInput`);
                if (shape) decisions.shape = shape.value;
                if (conflict) decisions.conflict = conflict.value;
                const bk = document.getElementById(`brokerSpendInput`);
                const dp = document.getElementById(`depthSpendInput`);
                const pe = document.getElementById(`peripherySpendInput`);
                if (bk) decisions.brokerSpend = parseFloat(bk.value);
                if (dp) decisions.depthSpend = parseFloat(dp.value);
                if (pe) decisions.peripherySpend = parseFloat(pe.value);
                const parts = [decisions.brokerSpend, decisions.depthSpend, decisions.peripherySpend];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round((decisions.brokerSpend + decisions.depthSpend + decisions.peripherySpend) * 10) / 10;
                if (total > this.BUDGET_CAP + 0.001) {
                    warn(`warn_alloc_over`); return false;
                }
                if (total <= 0) {
                    warn(`warn_alloc_zero`); return false;
                }
            } else if (round === 3) {
                const ult = document.getElementById(`ultimatumInput`);
                const bs = document.getElementById(`brokerStanceInput`);
                const inv = document.getElementById(`innovationInput`);
                const lk = document.getElementById(`lockinSpendInput`);
                if (ult) decisions.ultimatum = ult.value;
                if (bs) decisions.brokerStance = bs.value;
                if (inv) decisions.innovation = inv.value;
                if (lk) decisions.lockinSpend = parseFloat(lk.value);
                if (!Number.isFinite(decisions.lockinSpend) || decisions.lockinSpend < 0) {
                    warn(`warn_lockin_negative`); return false;
                }
            } else if (round === 4) {
                const ap = document.getElementById(`appropriateInput`);
                const re = document.getElementById(`reoptimizeInput`);
                const fb = document.getElementById(`feedbackRuleInput`);
                const cv = document.getElementById(`convictionInput`);
                if (ap) decisions.appropriate = ap.value;
                if (re) decisions.reoptimize = re.value;
                if (fb) decisions.feedbackRule = fb.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let centralityDelta = 0, appropDelta = 0, trustDelta = 0;
            let spend = 0, positions = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: advantage comes from network POSITION, not the module or partner count.
                switch (d.diag) {
                    case `position`: centralityDelta += 9; appropDelta += 3; coachKey = `coach_r1_position`; break;
                    case `technology`: centralityDelta -= 4; appropDelta -= 1; coachKey = `coach_r1_technology`; break;
                    case `count`: centralityDelta -= 5; trustDelta -= 1; coachKey = `coach_r1_count`; break;
                    case `defend`: centralityDelta -= 6; appropDelta -= 3; coachKey = `coach_r1_defend`; break;
                }

                // Prioritise the high-value structural holes (Burt), not the single hub or cheap periphery.
                switch (d.hole) {
                    case `broker`: centralityDelta += 6; appropDelta += 3; if (d.diag === `position`) coachKey = `coach_r1_sharp`; break;
                    case `central`: centralityDelta += 2; trustDelta -= 4; break;
                    case `cheap`: centralityDelta -= 4; coachKey = `coach_r1_cheap`; break;
                }

                // Performance-feedback: search under shortfall rather than defend the status quo.
                if (d.search >= 55) { centralityDelta += 4; }
                else if (d.search <= 25) { centralityDelta -= 5; appropDelta -= 1; coachKey = `coach_r1_lowsearch`; }

                summaryKey = (d.diag === `position` && d.hole === `broker`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Portfolio shape: a few deep high-rent positions beat many shallow vanity ties.
                switch (d.shape) {
                    case `deepfew`: centralityDelta += 9; appropDelta += 5; positions = 4; coachKey = `coach_r2_deepfew`; break;
                    case `manyshallow`: centralityDelta -= 5; trustDelta -= 3; positions = 7; coachKey = `coach_r2_manyshallow`; break;
                    case `onedeep`: centralityDelta += 3; appropDelta += 1; trustDelta -= 3; positions = 1; coachKey = `coach_r2_onedeep`; break;
                }

                // Over-committing past the engineering-attention cap degrades delivery (the 22% falls further).
                if (positions > this.POSITION_CAP) {
                    centralityDelta -= 4; trustDelta -= 3; appropDelta -= 2;
                }

                // The conflicting tie: commit to one; straddling both triggers distrust and retaliation.
                switch (d.conflict) {
                    case `commit`: centralityDelta += 6; appropDelta += 3; trustDelta += 5; if (d.shape === `deepfew`) coachKey = `coach_r2_committed`; break;
                    case `both`: centralityDelta -= 4; trustDelta -= 11; ds.straddled = true; coachKey = `coach_r2_straddle`; break;
                    case `neither`: centralityDelta -= 3; appropDelta -= 1; coachKey = `coach_r2_neither`; break;
                }

                // Budget allocation: weight the broker seats, not the cheap periphery spread.
                spend = d.brokerSpend + d.depthSpend + d.peripherySpend;
                if (d.brokerSpend >= 12) { centralityDelta += 5; appropDelta += 3; }
                else if (d.brokerSpend < 6) { centralityDelta -= 4; }
                if (d.peripherySpend >= 10) { centralityDelta -= 4; coachKey = `coach_r2_periphery`; }

                summaryKey = (d.shape === `deepfew` && d.conflict === `commit` && d.brokerSpend >= 12) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Exclusivity ultimatum: re-confirm the committed choice; caving or straddling both hurt.
                switch (d.ultimatum) {
                    case `reframe`: trustDelta += 7; appropDelta += 3; coachKey = `coach_r3_reframe`; break;
                    case `cave`: appropDelta -= 6; centralityDelta -= 4; coachKey = `coach_r3_cave`; break;
                    case `ignore`: trustDelta -= 8; appropDelta -= 4; ds.straddled = true; coachKey = `coach_r3_ignore`; break;
                }

                // Defend against disintermediation with lock-in, not by broadcasting connections.
                switch (d.brokerStance) {
                    case `lockin`: centralityDelta += 8; appropDelta += 7; coachKey = (d.ultimatum === `reframe`) ? `coach_r3_lockin` : coachKey; break;
                    case `broadcast`: centralityDelta -= 6; appropDelta -= 5; ds.disintermediated = true; coachKey = `coach_r3_broadcast`; break;
                    case `withdraw`: centralityDelta -= 5; appropDelta -= 1; coachKey = `coach_r3_withdraw`; break;
                }

                // Innovation tie: take the access with containment, never leak the full roadmap.
                switch (d.innovation) {
                    case `contain`: appropDelta += 6; centralityDelta += 3; break;
                    case `open`: appropDelta -= 6; trustDelta -= 3; ds.leaked = true; coachKey = `coach_r3_leak`; break;
                    case `decline`: centralityDelta -= 1; break;
                }

                // Lock-in investment — but only what the remaining budget can actually fund (the cap binds).
                const remaining = Math.max(0, this.BUDGET_CAP - ds.budgetUsed);
                const funded = Math.min(d.lockinSpend, remaining);
                spend = funded;
                if (d.lockinSpend > remaining + 0.001) {
                    appropDelta -= 3; coachKey = `coach_r3_unfunded`;
                }
                if (funded >= 4) { appropDelta += 6; centralityDelta += 3; }
                else if (funded >= 2) { appropDelta += 2; }
                else { appropDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r3_nolockin`; }

                summaryKey = (d.ultimatum === `reframe` && d.brokerStance === `lockin` && d.innovation === `contain`) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // Appropriate the value: install mechanisms, don't trust goodwill or abandon the network.
                switch (d.appropriate) {
                    case `mechanisms`: appropDelta += 13; centralityDelta += 4; coachKey = `coach_r4_mechanisms`; break;
                    case `goodwill`: appropDelta -= 10; coachKey = `coach_r4_goodwill`; break;
                    case `undercut`: appropDelta -= 7; centralityDelta -= 6; coachKey = `coach_r4_undercut`; break;
                }

                // Re-optimise after the rival's move: double down on rent seats, exit vanity ties.
                switch (d.reoptimize) {
                    case `double`: centralityDelta += 8; appropDelta += 4; if (d.appropriate === `mechanisms`) coachKey = `coach_r4_double`; break;
                    case `expand`: centralityDelta -= 5; trustDelta -= 3; coachKey = `coach_r4_expand`; break;
                    case `hold`: appropDelta -= 2; coachKey = `coach_r4_hold`; break;
                }

                // Feedback rule for the next cycle: a real aspiration, not a vanity count.
                switch (d.feedbackRule) {
                    case `aspiration`: centralityDelta += 4; appropDelta += 4; break;
                    case `vanity`: centralityDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r4_vanity` : coachKey; break;
                    case `none`: appropDelta -= 2; break;
                }

                // Conviction nudges appropriation.
                appropDelta += Math.round((d.conviction - 60) / 12);

                summaryKey = (d.appropriate === `mechanisms` && d.reoptimize === `double` && d.feedbackRule === `aspiration`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting.
            ds.budgetUsed = Math.min(this.BUDGET_CAP, Math.round((ds.budgetUsed + spend) * 10) / 10);
            if (positions > 0) ds.positions = positions;

            // Lingering penalties: a straddled conflicting tie keeps eroding trust; a leak keeps eroding rent.
            if (ds.straddled && round >= 3) trustDelta -= 3;
            if (ds.leaked && round === 4) appropDelta -= 4;
            if (ds.disintermediated && round === 4) { centralityDelta -= 4; appropDelta -= 4; }

            ds.centrality = Math.max(0, Math.min(100, ds.centrality + centralityDelta));
            ds.approp = Math.max(0, Math.min(100, ds.approp + appropDelta));
            ds.trust = Math.max(0, Math.min(100, ds.trust + trustDelta));

            ds.centralityHistory.push(Math.round(ds.centrality));
            ds.appropHistory.push(Math.round(ds.approp));
            ds.trustHistory.push(Math.round(ds.trust));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                centrality: Math.round(ds.centrality),
                centralityDelta: Math.round(centralityDelta),
                approp: Math.round(ds.approp),
                appropDelta: Math.round(appropDelta),
                trust: Math.round(ds.trust),
                trustDelta: Math.round(trustDelta),
                budgetUsed: ds.budgetUsed,
                positions: ds.positions,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

