                search.addEventListener(`input`, function() { searchReadout.textContent = search.value; });
            }

            // Budget allocation live total.
            const allocIds = [`brokerSpendInput`, `depthSpendInput`, `peripherySpendInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (allocReadout) allocReadout.textContent = `$` + total + `M`;
                const bar = document.querySelector(`.netadvsim-alloc-readout`);
                if (bar) bar.style.color = (total > self.BUDGET_CAP + 0.001) ? `#f87171` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
