        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const centrality = Math.round(ds.centrality);
            const approp = Math.round(ds.approp);
            const trust = Math.round(ds.trust);

            const hitCentrality = centrality >= this.TARGET_CENTRALITY;
            const hitApprop = approp >= this.TARGET_APPROP;
            const healthyTrust = trust >= 55;
            const composite = Math.round(centrality * 0.40 + approp * 0.40 + trust * 0.20);

            let performanceKey = `squeezed`;
            if (hitCentrality && hitApprop && healthyTrust && composite >= 72) performanceKey = `durable`;
            else if (hitCentrality && hitApprop) performanceKey = `rent_fragile`;
            else if (hitCentrality && !hitApprop) performanceKey = `value_not_captured`;
            else if (ds.straddled && trust < 40) performanceKey = `straddled`;
            else if (centrality > this.START_CENTRALITY + 25) performanceKey = `better_short`;
            // Stable, language-independent tier handle for the grading/reporting layer (read from domainState).
            ds.performanceTier = performanceKey;
            // Localized label for the debrief overlay (fixes English label leaking on non-EN screens).
            const performance = window.mySimulation.t(`tier_` + performanceKey);

            const insights = [];
            if (hitCentrality && hitApprop && healthyTrust) insights.push(window.mySimulation.t(`insight_durable`));
            else if (hitCentrality && !hitApprop) insights.push(window.mySimulation.t(`insight_notcaptured`));
            else if (!hitCentrality) insights.push(window.mySimulation.t(`insight_short`));

            if (ds.straddled) insights.push(window.mySimulation.t(`insight_straddle`));
            if (ds.disintermediated) insights.push(window.mySimulation.t(`insight_disinter`));
            if (ds.leaked) insights.push(window.mySimulation.t(`insight_leak`));
            if (ds.positions > this.POSITION_CAP) insights.push(window.mySimulation.t(`insight_overcommit`));
            if (hitCentrality && hitApprop && healthyTrust) insights.push(window.mySimulation.t(`insight_lasts`));

            return {
                centrality: centrality,
                approp: approp,
                trust: trust,
                hitCentrality: hitCentrality,
                hitApprop: hitApprop,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.straddled && state.currentPeriod >= 2) return window.mySimulation.t(`hint_straddle`);
            if (ds.disintermediated) return window.mySimulation.t(`hint_disinter`);
            if (ds.approp < 25 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_capture`);
            if (state.currentPeriod >= 3 && ds.centrality < 45) return window.mySimulation.t(`hint_behind`);
            if (ds.centrality >= this.TARGET_CENTRALITY && ds.approp >= this.TARGET_APPROP && ds.trust >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

